-- 0002 — crm seed data: config_entries + dictionary tables (consolidated).
-- Replaces 0002_seed_config + 20261107180000_seed_dictionaries +
-- 20261107183000_legal_forms_iso20275 + audit backfills + data bits of
-- later deltas. Dict seeds write their *_audit INSERT trail inline per
-- the seed-audit-trail standard (config_entries is not auditable).

SELECT pg_catalog.setval('crm.config_entries_id_seq', 10, true);
SELECT pg_catalog.setval('crm.account_kinds_id_seq', 2, true);
SELECT pg_catalog.setval('crm.company_dimensions_id_seq', 4, true);
SELECT pg_catalog.setval('crm.consent_types_id_seq', 4, true);
SELECT pg_catalog.setval('crm.contact_types_id_seq', 3, true);
SELECT pg_catalog.setval('crm.customer_link_types_id_seq', 4, true);
SELECT pg_catalog.setval('crm.customer_types_id_seq', 5, true);
SELECT pg_catalog.setval('crm.legal_forms_id_seq', 3597, true);
SELECT pg_catalog.setval('crm.local_address_types_id_seq', 5, true);
SELECT pg_catalog.setval('crm.marketing_qualifications_id_seq', 4, true);
SELECT pg_catalog.setval('crm.qualifications_id_seq', 5, true);


-- ─── Seed audit trail (seed-audit-trail standard) ───────────────────────

SELECT t.id, t.uuid, 'INSERT', t.created_at, 'initial-setup', t.version,
  jsonb_strip_nulls((SELECT jsonb_object_agg(kv.key, jsonb_build_object('old', null, 'new', kv.value)) FROM jsonb_each(to_jsonb(t)) kv))
FROM crm.account_kinds t
WHERE NOT EXISTS (SELECT 1 FROM crm.account_kinds_audit a WHERE a.entity_uuid = t.uuid);


SELECT t.id, t.uuid, 'INSERT', t.created_at, 'initial-setup', t.version,
  jsonb_strip_nulls((SELECT jsonb_object_agg(kv.key, jsonb_build_object('old', null, 'new', kv.value)) FROM jsonb_each(to_jsonb(t)) kv))
